const esc = s => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const items = $input.all().map(i => i.json).filter(a => a && a.title);

const cards = items.map(a => {
  const text = Array.isArray(a.content) ? a.content.join('\n\n') : (a.content || 'Pas de contenu.');
  const body = esc(text).replace(/\n/g, '<br>');
  return `
    <div class="card">
      ${a.image ? `<img src="${esc(a.image)}" alt="${esc(a.title)}" />` : ''}
      <details>
        <summary class="title">${esc(a.title)}</summary>
        <div class="content">${body}</div>
      </details>
    </div>`;
}).join('');

const html = `<!DOCTYPE html>
<html lang="fr"><head><meta charset="UTF-8">
<title>Dashboard Trends</title>
<style>
  body { font-family: Arial, sans-serif; background:#f4f4f4; margin:0; padding:20px; }
  .grid { display:grid; grid-template-columns: repeat(auto-fill, minmax(280px,1fr)); gap:20px; align-items:start; }
  .card { background:#fff; border-radius:8px; box-shadow:0 2px 6px rgba(0,0,0,.1); padding:15px; }
  .card img { width:100%; height:160px; object-fit:cover; border-radius:6px; }
  .title { cursor:pointer; color:#2563eb; font-weight:bold; margin:10px 0; }
  .content { margin-top:10px; font-size:14px; color:#333; line-height:1.5; }
</style></head>
<body>
  <h1>Articles tendance</h1>
  <div class="grid">${cards || '<p>Aucun article.</p>'}</div>
</body></html>`;

return [{ json: { html } }];
